import React, { useState, useEffect } from "react";
import Container from "react-bootstrap/Container";
import Nav from "react-bootstrap/Nav";
import Navb from "react-bootstrap/Navbar";
//import { useNavigate } from "react-router-dom";
import api from "../api";

const Navbar = () => {
  //const navigate = useNavigate();
  const [isAuthor, setIsAuthor] = useState(false);
  const [loggedIn, setLoggedIn] = useState(!!localStorage.getItem("token"));

  useEffect(() => {
    const checkAuthorStatus = async () => {
      if (loggedIn) {
        try {
          const response = await api.get("/auth/is-author", {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          });
          setIsAuthor(response.data);
        } catch (err) {
          console.error("Error fetching user profile:", err);
        }
      }
    };
    checkAuthorStatus();
  }, [loggedIn]);

  useEffect(() => {
    setLoggedIn(!!localStorage.getItem("token"));
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    //navigate("/login");
  };

  return (
    <Navb
      expand="lg"
      className="bg-dark border-bottom border-body"
      data-bs-theme="dark"
    >
      <Nav id="inner" className="justify-content-end">
        <Nav.Item>
          <Navb.Brand href="/">My Reading Site</Navb.Brand>
        </Nav.Item>
        <Nav.Item>
          <Navb.Toggle aria-controls="basic-navbar-nav" />
          <Navb.Collapse id="basic-navbar-nav" className="justify-content-end">
            <Nav>
              {loggedIn ? (
                <>
                  <Nav.Link href="/profile">User Profile</Nav.Link>
                  {isAuthor ? (
                    <Nav.Link href="/my-books">My Books</Nav.Link>
                  ) : (
                    <Nav.Link href="/become-author">Become an Author</Nav.Link>
                  )}
                  <Nav.Link href="/" onClick={handleLogout}>
                    Logout
                  </Nav.Link>
                </>
              ) : (
                <Nav.Link href="/login">Login</Nav.Link>
              )}
            </Nav>
          </Navb.Collapse>
        </Nav.Item>
      </Nav>
    </Navb>
  );
};

export default Navbar;
